        Show policy versions
      </button>
      {shown && (
        <ul>
          {(versions.data ?? []).map((v) => (
            <li key={v.version} data-testid="policy-line">
              {v.version} {v.from ?? 'start'} {v.key}={v.value} {count(v.version)}
            </li>
          ))}
